+export enum DeliverabilityStatus {
+  High = 'High',
+  Medium = 'Medium',
+  Low = 'Low',
+  Burned = 'Burned',
+  Unknown = 'Unknown',
+}
+
+export function deliverabilityStatusForScore(
+  score?: number | null,
+): DeliverabilityStatus {
+  if (score === undefined || score === null) {
+    return DeliverabilityStatus.Unknown;
+  }
+  if (score === 100) {
+    return DeliverabilityStatus.High;
+  }
+  if (score >= 98) {
+    return DeliverabilityStatus.Medium;
+  }
+  if (score >= 95) {
+    return DeliverabilityStatus.Low;
+  }
+  return DeliverabilityStatus.Burned;
+}
+
+export type EmailAccountProperties = {
+  smartleadInboxId: string | number;
+  smartleadClientId: string | number;
+  email: string;
+  createdAt?: string | Date;
+  deliverabilityScore?: number | null;
+  warmupReputation?: number | null;
+  tags?: string[];
+  campaignIds?: string[];
+};
+
+export class EmailAccount {
+  smartleadInboxId: string;
+  smartleadClientId: string;
+  email: string;
+  domain: string;
+  createdAt?: string;
+  deliverabilityScore?: number;
+  tags: string[];
+  campaignIds: string[];
+
+  constructor(properties: EmailAccountProperties) {
+    this.smartleadInboxId = String(properties.smartleadInboxId);
+    this.smartleadClientId = String(properties.smartleadClientId);
+    this.email = properties.email;
+    this.domain = this.email.split('@').pop()?.toLowerCase() ?? '';
+    this.createdAt = properties.createdAt
+      ? new Date(properties.createdAt).toISOString()
+      : undefined;
+    this.deliverabilityScore =
+      properties.deliverabilityScore ??
+      properties.warmupReputation ??
+      undefined;
+    this.tags = [...(properties.tags ?? [])];
+    this.campaignIds = [...new Set(properties.campaignIds ?? [])];
+  }
+
+  get warmupReputation(): number | undefined {
+    return this.deliverabilityScore;
+  }
+
+  get deliverabilityStatus(): DeliverabilityStatus {
+    return deliverabilityStatusForScore(this.deliverabilityScore);
+  }
+
+  get numberOfCampaignAssociated(): number {
+    return this.campaignIds.length;
+  }
+
+  toJSON() {
+    return {
+      smartleadInboxId: this.smartleadInboxId,
+      smartleadClientId: this.smartleadClientId,
+      email: this.email,
+      domain: this.domain,
+      createdAt: this.createdAt,
+      deliverabilityScore: this.deliverabilityScore,
+      warmupReputation: this.warmupReputation,
+      deliverabilityStatus: this.deliverabilityStatus,
+      tags: this.tags,
+      campaignIds: this.campaignIds,
+      numberOfCampaignAssociated: this.numberOfCampaignAssociated,
+    };
+  }
+}
