+import {
+  BadRequestException,
+  Injectable,
+  Logger,
+  NotFoundException,
+  Optional,
+} from '@nestjs/common';
+import { DatastoreService } from '../datastore/datastore.service';
+import { StoreDataDto } from '../datastore/dto/store.dto';
+import { documentType } from '../datastore/entites/documentType';
+import { SmartleadService } from '../smartlead/smartlead.service';
+import { EmailAccountDto, EmailAccountListDto } from './dto/emailAccount.dto';
+import { EmailAccount } from './entities/emailinfra.entity';
+
+const DEFAULT_CAMPAIGN_DAYS = 10;
+const DEFAULT_EMAILS_PER_INBOX_PER_DAY = 20;
+
+@Injectable()
+export class EmailinfraService {
+  private readonly logger = new Logger(EmailinfraService.name);
+
+  constructor(
+    @Optional() private readonly datastoreService?: DatastoreService,
+    @Optional() private readonly smartleadService?: SmartleadService,
+  ) {}
+
+  async getBestEmailAccountsForCampaign({
+    smartleadClientId,
+    numberOfDaysInCampaign = DEFAULT_CAMPAIGN_DAYS,
+    totalNumberOfEmailsToSend,
+    emailsPerInboxPerDay = DEFAULT_EMAILS_PER_INBOX_PER_DAY,
+  }: EmailAccountListDto): Promise<EmailAccount[]> {
+    if (numberOfDaysInCampaign <= 0 || emailsPerInboxPerDay <= 0) {
+      throw new BadRequestException(
+        'Campaign days and emails per inbox per day must be positive',
+      );
+    }
+
+    const requiredPoolSize = Math.floor(
+      totalNumberOfEmailsToSend /
+        numberOfDaysInCampaign /
+        emailsPerInboxPerDay,
+    );
+    if (requiredPoolSize <= 0) {
+      return [];
+    }
+
+    const accounts = await this.getEmailAccountBySmartleadClientId(
+      smartleadClientId,
+    );
+    const inboxesByDomain = accounts.reduce<Record<string, number>>(
+      (counts, account) => {
+        counts[account.domain] = (counts[account.domain] ?? 0) + 1;
+        return counts;
+      },
+      {},
+    );
+
+    return accounts
+      .sort((left, right) => {
+        const scoreDifference =
+          (right.deliverabilityScore ?? Number.NEGATIVE_INFINITY) -
+          (left.deliverabilityScore ?? Number.NEGATIVE_INFINITY);
+        if (scoreDifference !== 0) return scoreDifference;
+
+        const campaignDifference =
+          left.numberOfCampaignAssociated - right.numberOfCampaignAssociated;
+        if (campaignDifference !== 0) return campaignDifference;
+
+        const domainDifference =
+          inboxesByDomain[left.domain] - inboxesByDomain[right.domain];
+        if (domainDifference !== 0) return domainDifference;
+
+        return (
+          this.creationTimestamp(left.createdAt) -
+          this.creationTimestamp(right.createdAt)
+        );
+      })
+      .slice(0, requiredPoolSize);
+  }
+
+  async associateEmailAccountsWithCampaign({
+    emailAccountIds,
+    campaignId,
+  }: {
+    emailAccountIds: Array<string | number>;
+    campaignId: string;
+  }): Promise<EmailAccount[]> {
+    const uniqueIds = [...new Set(emailAccountIds.map(String))];
+    const accounts = await Promise.all(
+      uniqueIds.map((smartleadInboxId) =>
+        this.findEmailAccount(smartleadInboxId),
+      ),
+    );
+    const missingIds = uniqueIds.filter((_, index) => !accounts[index]);
+    if (missingIds.length > 0) {
+      throw new NotFoundException(
+        `Email accounts not found: ${missingIds.join(', ')}`,
+      );
+    }
+
+    return Promise.all(
+      accounts.map(async (account) => {
+        if (!account.campaignIds.includes(campaignId)) {
+          account.campaignIds.push(campaignId);
+          await this.persist(account);
+        }
+        return account;
+      }),
+    );
+  }
+
+  async saveEmailAccount(emailAccount: EmailAccountDto): Promise<EmailAccount> {
+    this.assertDependencies();
+    let remoteAccount: any;
+    let warmupDetails: any;
+    try {
+      [remoteAccount, warmupDetails] = await Promise.all([
+        this.smartleadService.getEmailAccountById(
+          emailAccount.smartleadInboxId,
+        ),
+        this.smartleadService.getEmailAccountWarmupDetails(
+          emailAccount.smartleadInboxId,
+        ),
+      ]);
+    } catch (error) {
+      if (error instanceof NotFoundException) throw error;
+      throw error;
+    }
+
+    if (!remoteAccount || remoteAccount.id === undefined) {
+      throw new NotFoundException('Email account not found');
+    }
+
+    const existing = await this.findEmailAccount(emailAccount.smartleadInboxId);
+    const account = new EmailAccount({
+      smartleadInboxId: remoteAccount.id,
+      smartleadClientId:
+        remoteAccount.client_id ?? emailAccount.smartleadClientId,
+      email:
+        remoteAccount.from_email ?? remoteAccount.email ?? emailAccount.email,
+      createdAt: remoteAccount.created_at ?? remoteAccount.createdAt,
+      deliverabilityScore:
+        warmupDetails?.warmup_reputation ??
+        warmupDetails?.reputation ??
+        warmupDetails?.warmupReputation,
+      tags: emailAccount.tags ?? remoteAccount.tags ?? existing?.tags,
+      campaignIds: emailAccount.campaignIds ?? existing?.campaignIds,
+    });
+    await this.persist(account);
+    return account;
+  }
+
+  async getEmailAccount(
+    emailAccount: EmailAccountDto | string | number,
+  ): Promise<EmailAccount> {
+    const id =
+      typeof emailAccount === 'object'
+        ? emailAccount.smartleadInboxId
+        : emailAccount;
+    const account = await this.findEmailAccount(String(id));
+    if (!account) throw new NotFoundException('Email account not found');
+    return account;
+  }
+
+  async getAllEmailAccounts(
+    pageOrPagination: number | { page?: number; pageSize?: number } = 0,
+    requestedPageSize = 50,
+  ): Promise<EmailAccount[]> {
+    this.assertDependencies(false);
+    const page =
+      typeof pageOrPagination === 'number'
+        ? pageOrPagination
+        : (pageOrPagination.page ?? 0);
+    const pageSize =
+      typeof pageOrPagination === 'number'
+        ? requestedPageSize
+        : (pageOrPagination.pageSize ?? 50);
+    const response = await this.datastoreService.getByField({
+      documentType: documentType.EMAIL_ACCOUNT,
+      fieldKey: 'data.documentType',
+      fieldValue: documentType.EMAIL_ACCOUNT,
+      pagination: { page, pageSize },
+    });
+    return (response?.data ?? []).map((account) => this.hydrate(account));
+  }
+
+  async getEmailAccountByEmail(email: string): Promise<EmailAccount | undefined> {
+    return this.getFirstByField('data.email', email.toLowerCase());
+  }
+
+  async getEmailAccountBySmartleadClientId(
+    smartleadClientId: string | number,
+  ): Promise<EmailAccount[]> {
+    this.assertDependencies(false);
+    const response = await this.datastoreService.getByField({
+      documentType: documentType.EMAIL_ACCOUNT,
+      fieldKey: 'data.smartleadClientId',
+      fieldValue: String(smartleadClientId),
+    });
+    return (response?.data ?? []).map((account) => this.hydrate(account));
+  }
+
+  async deleteEmailAccount(
+    emailAccount: EmailAccountDto | string | number,
+  ) {
+    const id =
+      typeof emailAccount === 'object'
+        ? emailAccount.smartleadInboxId
+        : emailAccount;
+    await this.getEmailAccount(id);
+    return this.datastoreService.remove({
+      id: String(id),
+      documentType: documentType.EMAIL_ACCOUNT,
+    });
+  }
+
+  private async findEmailAccount(
+    smartleadInboxId: string | number,
+  ): Promise<EmailAccount | undefined> {
+    this.assertDependencies(false);
+    const response = await this.datastoreService.getById({
+      id: String(smartleadInboxId),
+      documentType: documentType.EMAIL_ACCOUNT,
+    });
+    return response?.data ? this.hydrate(response.data) : undefined;
+  }
+
+  private async getFirstByField(
+    fieldKey: string,
+    fieldValue: string,
+  ): Promise<EmailAccount | undefined> {
+    this.assertDependencies(false);
+    const response = await this.datastoreService.getByField({
+      documentType: documentType.EMAIL_ACCOUNT,
+      fieldKey,
+      fieldValue,
+    });
+    return response?.data?.[0] ? this.hydrate(response.data[0]) : undefined;
+  }
+
+  private async persist(account: EmailAccount): Promise<void> {
+    this.assertDependencies(false);
+    await this.datastoreService.store(
+      new StoreDataDto({
+        data: {
+          ...account.toJSON(),
+          documentType: documentType.EMAIL_ACCOUNT,
+        },
+        context: {
+          documentType: documentType.EMAIL_ACCOUNT,
+          uniqueId: account.smartleadInboxId,
+        },
+      }),
+    );
+  }
+
+  private hydrate(account: any): EmailAccount {
+    return new EmailAccount({
+      ...account,
+      deliverabilityScore:
+        account.deliverabilityScore ?? account.warmupReputation,
+    });
+  }
+
+  private creationTimestamp(createdAt?: string): number {
+    if (!createdAt) return Number.POSITIVE_INFINITY;
+    const timestamp = new Date(createdAt).getTime();
+    return Number.isNaN(timestamp) ? Number.POSITIVE_INFINITY : timestamp;
+  }
+
+  private assertDependencies(requireSmartlead = true): void {
+    if (!this.datastoreService) {
+      throw new Error('DatastoreService is not configured');
+    }
+    if (requireSmartlead && !this.smartleadService) {
+      throw new Error('SmartleadService is not configured');
+    }
+  }
+}
